<script lang="ts">import Icon from '$lib/components/Icon.svelte';import {children,basename,type Tree} from '$lib/files/model.js';export let tree:Tree;export let folder:string;export let current:string;export let onOpen:(path:string)=>void;export let depth=0;let expanded=false;$: open=expanded||current===folder||current.startsWith(folder+'/');$: folders=children(tree,folder).filter(p=>tree[p].kind==='folder');</script>
<div class="x-tree-row" style={'--depth:'+Math.min(depth,7)}><button type="button" class="x-tree-toggle" disabled={!folders.length} aria-label={(open?'Collapse ':'Expand ')+basename(folder)} on:click={()=>{if(open&&current.startsWith(folder+'/'))onOpen(folder);expanded=!open;}}>{folders.length?(open?'▾':'▸'):'·'}</button><button type="button" class="x-tree-node" class:selected={current===folder} on:click={()=>onOpen(folder)}><Icon name="Projects"/><span>{basename(folder)}</span></button></div>{#if open}{#each folders as child (child)}<svelte:self {tree} folder={child} {current} {onOpen} depth={depth+1}/>{/each}{/if}
